arguments.file_text:
@page "/apply"
@rendermode InteractiveServer
@using sv_9b20c57dc3c24dd39454d389dbd404b0.Models
@using sv_9b20c57dc3c24dd39454d389dbd404b0.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    @* Step Indicator Bar *@
    <div class="step-indicator">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var stepIndex = i;
            var stepClass = GetStepClass(stepIndex);
            <div class="step @stepClass" @onclick="() => NavigateToStep(stepIndex)">
                <div class="step-circle">
                    @if (stepIndex < CurrentStep)
                    {
                        <span class="checkmark">✓</span>
                    }
                    else
                    {
                        <span>@(stepIndex + 1)</span>
                    }
                </div>
                <div class="step-label">@StepNames[stepIndex]</div>
            </div>
            @if (i < StepNames.Length - 1)
            {
                <div class="step-connector @(i < CurrentStep ? "completed" : "")"></div>
            }
        }
    </div>

    @* Validation Errors *@
    @if (Errors.Any())
    {
        <div class="validation-errors">
            <ul>
                @foreach (var error in Errors)
                {
                    <li>@error</li>
                }
            </ul>
        </div>
    }

    @* Step Content *@
    @if (IsSubmitted)
    {
        <div class="confirmation">
            <h2>✓ Application Submitted Successfully!</h2>
            <p>Your application ID is: <strong>@ApplicationId</strong></p>
            <p>Thank you for your application. We will be in touch soon.</p>
        </div>
    }
    else
    {
        switch (CurrentStep)
        {
            case 0:
                @RenderPersonalInfo()
                break;
            case 1:
                @RenderWorkHistory()
                break;
            case 2:
                @RenderReferences()
                break;
            case 3:
                @RenderCoverLetter()
                break;
            case 4:
                @RenderReview()
                break;
        }
    }
</div>

@* Step 1: Personal Info *@
@{ RenderFragment RenderPersonalInfo() =>
    @<div class="step-content">
        <h2>Personal Information</h2>
        <div class="form-group">
            <label for="fullName">Full Name *</label>
            <input id="fullName" type="text" @bind="FullName" @bind:event="oninput" placeholder="Enter your full name" />
        </div>
        <div class="form-group">
            <label for="email">Email *</label>
            <input id="email" type="email" @bind="Email" @bind:event="oninput" placeholder="Enter your email" />
        </div>
        <div class="form-group">
            <label for="phone">Phone *</label>
            <input id="phone" type="tel" @bind="Phone" @bind:event="oninput" placeholder="Enter your phone number" />
        </div>
        <div class="form-group">
            <label for="address">Address *</label>
            <textarea id="address" @bind="Address" @bind:event="oninput" placeholder="Enter your address" rows="3"></textarea>
        </div>
        <div class="form-buttons">
            <button class="btn-next" @onclick="NextStep">Next</button>
        </div>
    </div>;
}

@* Step 2: Work History *@
@{ RenderFragment RenderWorkHistory() =>
    @<div class="step-content">
        <h2>Work History</h2>
        @for (int i = 0; i < WorkEntries.Count; i++)
        {
            var index = i;
            <div class="work-entry-card">
                <div class="work-entry-header">
                    <h3>Position @(index + 1)</h3>
                    @if (WorkEntries.Count > 1)
                    {
                        <button class="btn-remove" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                    }
                </div>
                <div class="form-group">
                    <label>Company Name *</label>
                    <input type="text" @bind="WorkEntries[index].Company" @bind:event="oninput" placeholder="Company name" />
                </div>
                <div class="form-group">
                    <label>Job Title *</label>
                    <input type="text" @bind="WorkEntries[index].Title" @bind:event="oninput" placeholder="Job title" />
                </div>
                <div class="form-row">
                    <div class="form-group">
                        <label>Start Date *</label>
                        <input type="date" @bind="WorkEntries[index].StartDate" />
                    </div>
                    <div class="form-group">
                        <label>End Date</label>
                        <input type="date" @bind="WorkEntries[index].EndDate" disabled="@WorkEntries[index].IsCurrent" />
                    </div>
                </div>
                <div class="form-group checkbox-group">
                    <input type="checkbox" id="current-@index" @bind="WorkEntries[index].IsCurrent" />
                    <label for="current-@index">I currently work here</label>
                </div>
                <div class="form-group">
                    <label>Description *</label>
                    <textarea @bind="WorkEntries[index].Description" @bind:event="oninput" placeholder="Describe your role and responsibilities" rows="3"></textarea>
                </div>
            </div>
        }
        <button class="btn-add" @onclick="AddWorkEntry">+ Add Another Position</button>
        <div class="form-buttons">
            <button class="btn-back" @onclick="PreviousStep">Back</button>
            <button class="btn-next" @onclick="NextStep">Next</button>
        </div>
    </div>;
}

@* Step 3: References *@
@{ RenderFragment RenderReferences() =>
    @<div class="step-content">
        <h2>References</h2>
        @for (int i = 0; i < ReferenceEntries.Count; i++)
        {
            var index = i;
            <div class="reference-card">
                <div class="work-entry-header">
                    <h3>Reference @(index + 1)</h3>
                    @if (ReferenceEntries.Count > 2)
                    {
                        <button class="btn-remove" @onclick="() => RemoveReference(index)">Remove</button>
                    }
                </div>
                <div class="form-group">
                    <label>Name *</label>
                    <input type="text" @bind="ReferenceEntries[index].Name" @bind:event="oninput" placeholder="Reference name" />
                </div>
                <div class="form-group">
                    <label>Relationship *</label>
                    <input type="text" @bind="ReferenceEntries[index].Relationship" @bind:event="oninput" placeholder="e.g., Former Manager" />
                </div>
                <div class="form-group">
                    <label>Email *</label>
                    <input type="email" @bind="ReferenceEntries[index].Email" @bind:event="oninput" placeholder="Reference email" />
                </div>
                <div class="form-group">
                    <label>Phone *</label>
                    <input type="tel" @bind="ReferenceEntries[index].Phone" @bind:event="oninput" placeholder="Reference phone" />
                </div>
            </div>
        }
        @if (ReferenceEntries.Count < 3)
        {
            <button class="btn-add" @onclick="AddReference">+ Add Reference</button>
        }
        <div class="form-buttons">
            <button class="btn-back" @onclick="PreviousStep">Back</button>
            <button class="btn-next" @onclick="NextStep">Next</button>
        </div>
    </div>;
}

@* Step 4: Cover Letter *@
@{ RenderFragment RenderCoverLetter() =>
    @<div class="step-content">
        <h2>Cover Letter</h2>
        <div class="form-group">
            <label for="coverLetter">Write your cover letter *</label>
            <textarea id="coverLetter" @bind="CoverLetterText" @bind:event="oninput" placeholder="Tell us why you're a great fit for this position..." rows="12" maxlength="2000"></textarea>
            <div class="character-count">@CoverLetterText.Length / 2000 characters</div>
        </div>
        <div class="form-buttons">
            <button class="btn-back" @onclick="PreviousStep">Back</button>
            <button class="btn-next" @onclick="NextStep">Next</button>
        </div>
    </div>;
}

@* Step 5: Review & Submit *@
@{ RenderFragment RenderReview() =>
    @<div class="step-content">
        <h2>Review & Submit</h2>

        <div class="review-section">
            <div class="review-header">
                <h3>Personal Information</h3>
                <button class="btn-edit" @onclick="() => GoToStep(0)">Edit</button>
            </div>
            <dl>
                <dt>Full Name</dt><dd>@FullName</dd>
                <dt>Email</dt><dd>@Email</dd>
                <dt>Phone</dt><dd>@Phone</dd>
                <dt>Address</dt><dd>@Address</dd>
            </dl>
        </div>

        <div class="review-section">
            <div class="review-header">
                <h3>Work History</h3>
                <button class="btn-edit" @onclick="() => GoToStep(1)">Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="review-entry">
                    <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
                    <span>@entry.StartDate.ToString("MMM yyyy") — @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))</span><br />
                    <p>@entry.Description</p>
                </div>
            }
        </div>

        <div class="review-section">
            <div class="review-header">
                <h3>References</h3>
                <button class="btn-edit" @onclick="() => GoToStep(2)">Edit</button>
            </div>
            @foreach (var reference in ReferenceEntries)
            {
                <div class="review-entry">
                    <strong>@reference.Name</strong> (@reference.Relationship)<br />
