arguments.file_text:
.application-form {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem;
}

.application-form h1 {
    text-align: center;
    margin-bottom: 2rem;
    color: #1a1a2e;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    padding: 1rem 0;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    min-width: 80px;
}

.step.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    border: 2px solid #ddd;
    background: #fff;
    color: #999;
    transition: all 0.3s ease;
}

.step.active .step-circle {
    background: #4361ee;
    border-color: #4361ee;
    color: #fff;
}

.step.completed .step-circle {
    background: #2ecc71;
    border-color: #2ecc71;
    color: #fff;
}

.step.future .step-circle {
    background: #f0f0f0;
    border-color: #ddd;
    color: #999;
}

.step-label {
    margin-top: 0.5rem;
    font-size: 0.75rem;
    color: #999;
    text-align: center;
    white-space: nowrap;
}

.step.active .step-label {
    color: #4361ee;
    font-weight: 600;
}

.step.completed .step-label {
    color: #2ecc71;
    font-weight: 500;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #ddd;
    margin: 0 0.5rem;
    margin-bottom: 1.5rem;
    transition: background 0.3s ease;
}

.step-connector.completed {
    background: #2ecc71;
}

.checkmark {
    font-size: 1rem;
}

/* Validation Errors */
.validation-errors {
    background: #fff3f3;
    border: 1px solid #ff6b6b;
    border-radius: 8px;
    padding: 1rem;
    margin-bottom: 1.5rem;
}

.validation-errors ul {
    margin: 0;
    padding-left: 1.5rem;
}

.validation-errors li {
    color: #cc0000;
    margin-bottom: 0.25rem;
}

/* Step Content */
.step-content {
    background: #fff;
    border: 1px solid #e8e8e8;
    border-radius: 12px;
    padding: 2rem;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
}

.step-content h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    color: #1a1a2e;
}

/* Form Elements */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    color: #333;
    font-size: 0.9rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.6rem 0.8rem;
    border: 1px solid #ddd;
    border-radius: 6px;
    font-size: 0.95rem;
    transition: border-color 0.2s;
    box-sizing: border-box;
}

.form-group input:focus,
.form-group textarea:focus {
    outline: none;
    border-color: #4361ee;
    box-shadow: 0 0 0 3px rgba(67, 97, 238, 0.1);
}

.form-row {
    display: flex;
    gap: 1rem;
}

.form-row .form-group {
    flex: 1;
}

.checkbox-group {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.checkbox-group input[type="checkbox"] {
    width: auto;
}

.checkbox-group label {
    margin-bottom: 0;
    font-weight: normal;
}

/* Buttons */
.form-buttons {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    padding-top: 1.5rem;
    border-top: 1px solid #eee;
}

.btn-next,
.btn-submit {
    background: #4361ee;
    color: #fff;
    border: none;
    padding: 0.7rem 2rem;
    border-radius: 6px;
    font-size: 1rem;
    cursor: pointer;
    font-weight: 500;
    transition: background 0.2s;
    margin-left: auto;
}

.btn-next:hover,
.btn-submit:hover {
    background: #3451d1;
}

.btn-submit:disabled {
    background: #a0a0a0;
    cursor: not-allowed;
}

.btn-back {
    background: #f0f0f0;
    color: #333;
    border: 1px solid #ddd;
    padding: 0.7rem 2rem;
    border-radius: 6px;
    font-size: 1rem;
    cursor: pointer;
    font-weight: 500;
    transition: background 0.2s;
}

.btn-back:hover {
    background: #e0e0e0;
}

.btn-add {
    background: transparent;
    color: #4361ee;
